local a=require("fcs.comms.protocol")local b={}b.CMD_KIND="eh2_beacon_update"b.ACK_KIND="eh2_beacon_update_ack"b.CMD2_KIND="eh2_beacon_cmd"b.STATUS_KIND="eh2_beacon_status"b.OPS={enable=true,disable=true,verify=true,query=true,setPos=true,setInterval=true,reboot=true}function b.cmd(c,d,e,f)return{k=b.CMD2_KIND,op=c,token=d,args=e,target=f}end;function b.status(g,h)local i={}for j,k in pairs(h or{})do i[j]=k end;i.k=b.STATUS_KIND;i.id=g;return i end;function b.validToken(l)return type(l)=="string"and l:gsub("%s","")~=""end;function b.command(d,f)return{k=b.CMD_KIND,token=d,target=f}end;function b.ack(g)return{k=b.ACK_KIND,id=g}end;function b.encode(m)return a.encode(m)end;function b.decode(n)local i=a.decode(n)if type(i)~="table"then return nil end;if i.k==b.CMD_KIND or i.k==b.ACK_KIND or i.k==b.CMD2_KIND or i.k==b.STATUS_KIND then return i end;return nil end;function b.accepts(m,o)if type(m)~="table"or m.k~=b.CMD_KIND then return false end;if not b.validToken(o)then return false end;if not b.validToken(m.token)then return false end;return m.token==o end;function b.acceptsCmd(m,o)if type(m)~="table"or m.k~=b.CMD2_KIND then return false end;if not b.OPS[m.op]then return false end;if not b.validToken(o)then return false end;if not b.validToken(m.token)then return false end;return m.token==o end;function b.targeted(m,p)return m.target==nil or m.target==p end;return b